function syncWasteMovement(w){if(!inv||!pricing||!w)return;const loc=w.locationId||inv.settings.mainLocationId,dt=D(w.date),kind=w.recordKind==='consumption'?'consumption':'waste',sourceBase=`${kind}:${w.id}`,st=recordMovementStatus(w),validKeys=[];const upsert=(key,ingredientId,quantity)=>{validKeys.push(key);let m=(w.movementId&&A(inv.inventoryMovements).find(x=>x.id===w.movementId&&x.ingredientId===ingredientId))||A(inv.inventoryMovements).find(x=>x.sourceKey===key);const data={date:dt,time:w.time||'',movementType:w.eventType||'WASTE',ingredientId,quantity:N(quantity),fromLocationId:loc,toLocationId:'',reasonCode:w.reason||'',referenceType:kind==='consumption'?'consumptionRecord':'wasteRecord',referenceId:w.id,sourceKey:key,status:st,personnelId:w.reportedByPersonnelId||w.responsiblePersonnelId||'',personnelName:w.reportedByName||'',shift:w.shift||'',notes:w.notes||'',reviewStatus:w.reviewStatus||'',managerNote:w.managerNote||'',updatedAt:now()};if(m){Object.assign(m,data);if(w.type==='ingredient')w.movementId=m.id}else{m={id:uid('MOV',inv.inventoryMovements),...data,createdAt:w.createdAt||now(),createdBy:w.createdBy||'migration'};inv.inventoryMovements.push(m);if(w.type==='ingredient')w.movementId=m.id}};if(w.type==='ingredient')upsert(sourceBase,w.itemId,w.quantity);else if(w.type==='menu')for(const r of recipeAt(w.itemId,dt))upsert(`${sourceBase}:${r.ingredientId}`,r.ingredientId,N(w.quantity)*N(r.quantity));for(const m of A(inv.inventoryMovements).filter(x=>S(x.sourceKey).startsWith(sourceBase)&&!validKeys.includes(x.sourceKey)))m.status='void'}
async function syncLegacyToLedger(save=true){const before=A(inv.inventoryMovements).length,wasteIds=new Set(A(inv.wasteRecords).map(x=>x.id)),consumptionIds=new Set(A(inv.consumptionRecords).map(x=>x.id));for(const m of A(inv.inventoryMovements)){if(m.referenceType==='wasteRecord'&&m.referenceId&&!wasteIds.has(m.referenceId))m.status='void';if(m.referenceType==='consumptionRecord'&&m.referenceId&&!consumptionIds.has(m.referenceId))m.status='void'}for(const r of A(inv.stockReceipts)){r.locationId=r.locationId||inv.settings.mainLocationId;const key=`receipt:${r.id}`;let m=A(inv.inventoryMovements).find(x=>x.sourceKey===key);if(!m){inv.inventoryMovements.push({id:uid('MOV',inv.inventoryMovements),date:D(r.date),movementType:'PURCHASE_RECEIPT',ingredientId:r.ingredientId,quantity:N(r.quantity),fromLocationId:'',toLocationId:r.locationId,reasonCode:'PURCHASE',referenceType:'purchaseInvoice',referenceId:r.invoiceId||'',sourceKey:key,status:r.status==='void'?'void':(receiptIsPosted(r)?'posted':'pending'),unitCostToman:receiptUnitCost(r),createdAt:r.createdAt||now(),createdBy:'system'});}else m.status=r.status==='void'?'void':(receiptIsPosted(r)?'posted':'pending')}for(const w of A(inv.wasteRecords))syncWasteMovement(w);for(const c of A(inv.consumptionRecords))syncWasteMovement(c);if(save&&A(inv.inventoryMovements).length!==before)await saveInv('همگام‌سازی Ledger موجودی',false)}
async function saveInv(action,notify=true){inv.meta=inv.meta||{};inv.meta.schemaVersion='2.0.1';inv.meta.updatedAt=now();if(action)inv.changeLog.push({at:now(),action,actor:actor()});await RAYO_API_GATEWAY.saveModule('inventory',inv);if(notify)toastX('اطلاعات انبار ذخیره شد')}
async function savePricing(action){pricing.meta=pricing.meta||{};pricing.meta.schemaVersion='2.0.0';pricing.meta.updatedAt=now();if(action)pricing.changeLog.push({at:now(),action,actor:actor()});await RAYO_API_GATEWAY.saveModule('pricing',pricing)}
async function ensure(){if(loaded)return true;if(loading){while(loading)await new Promise(r=>setTimeout(r,30));return loaded}loading=true;try{await Promise.all([window.ivEnsureLoaded?.(),window.pcEnsureLoaded?.(),window.supEnsureLoaded?.(),window.crEnsureLoaded?.(true)]);inv=window.getInventoryState?.()||await RAYO_API_GATEWAY.loadOrBootstrap('inventory');pricing=window.getPricingState?.()||await RAYO_API_GATEWAY.loadOrBootstrap('pricing');suppliers=window.getSupplierState?.()||await RAYO_API_GATEWAY.loadOrBootstrap('suppliers').catch(()=>({suppliers:[],items:[],supplierItems:[]}));cash=window.getCashReportState?.()||null;hr=await RAYO_API_GATEWAY.loadOrBootstrap('hr').catch(()=>null);if(!inv||!pricing)throw Error('اطلاعات پایه انبار یا قیمت‌گذاری بارگذاری نشد');const changed=ensureSchema();/* Data-safety: schema normalization is in-memory only on load; never auto-save. It persists on the next explicit user operation. */await syncLegacyToLedger(false);ui.location=ui.location||inv.settings.mainLocationId;ui.countLocation=ui.countLocation||inv.settings.mainLocationId;loaded=true;return true}catch(e){window.RayoErrorLog?.capture?.(e,{source:'inventory-control-v10-load'});toastX(e.message||'خطا در آماده‌سازی کنترل انبار',true);return false}finally{loading=false}}
