function locationsPane(){const locs=activeLocations();return `<div class="grid grid-2"><div class="card"><div class="section-head"><h2>محل‌های نگهداری و مصرف</h2><button class="btn btn-primary" onclick="RayoInventoryV10.editLocation()">+ محل</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>کد</th><th>نام</th><th>نوع</th><th>سکشن</th><th></th></tr></thead><tbody>${A(inv.locations).map(l=>`<tr><td>${E(l.code)}</td><td><b>${E(l.name)}</b></td><td>${E(l.type==='main'?'انبار اصلی':'مصرفی')}</td><td>${E(l.section||'—')}</td><td><button class="btn btn-sm" onclick="RayoInventoryV10.editLocation('${l.id}')">ویرایش</button></td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="section-head"><h2>تنظیمات پایه</h2></div><div class="form-grid"><div class="field"><label>انبار اصلی</label><select id="v10MainLoc">${optionRows(locs,inv.settings.mainLocationId)}</select></div><div class="field"><label>Location پیش‌فرض فروش بدون نگاشت</label><select id="v10DefSaleLoc">${optionRows(locs,inv.settings.defaultSalesLocationId)}</select></div><div class="full hint"><b>روش محاسبه ثابت:</b> بهای مصرف دوره با میانگین موزون محاسبه می‌شود و ارزش روز موجودی از آخرین قیمت خرید معتبر استفاده می‌کند. این روش تنظیم قابل‌تغییر نیست، بنابراین به‌عنوان فیلد تنظیمات نمایش داده نمی‌شود.</div><div class="full"><button class="btn btn-primary" onclick="RayoInventoryV10.saveBaseSettings()">ذخیره تنظیمات</button></div></div></div></div><div class="card"><div class="section-head"><div><h2>نگاشت آیتم منو → محل تولید/مصرف</h2><p class="muted">این نگاشت تعیین می‌کند مصرف رسپی فروش از کدام موجودی سکشن کم شود.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>کد</th><th>آیتم منو</th><th>دسته</th><th>محل تولید</th></tr></thead><tbody>${A(pricing.menuItems).filter(m=>m.status!=='غیرفعال').map(m=>`<tr><td>${E(m.code||'')}</td><td>${E(m.name)}</td><td>${E(m.category||'')}</td><td><select onchange="RayoInventoryV10.mapMenu('${m.id}',this.value)"><option value="">پیش‌فرض</option>${optionRows(locs,m.productionLocationId||'')}</select></td></tr>`).join('')}</tbody></table></div></div>${helpCard('محل‌ها و نگاشت',['انبار اصلی محل ورود خرید است.','آشپزخانه، بار و قلیان موجودی مصرفی مستقل دارند.','برای تحلیل سکشن، آیتم‌های منو را به Location تولیدشان نگاشت کنید.','اگر آیتمی نگاشت نشده باشد از Location پیش‌فرض فروش کم می‌شود.'])}`}
function transferPane(){const locs=activeLocations(),ings=A(pricing.ingredients).filter(i=>i.status!=='غیرفعال'&&i.itemType!=='NON_STOCK'),rows=A(inv.inventoryMovements).filter(m=>['TRANSFER','RETURN_TO_WAREHOUSE'].includes(m.movementType)&&m.status!=='void').slice().sort((a,b)=>cmp(b.date,a.date)||S(b.createdAt).localeCompare(S(a.createdAt))).slice(0,300);return `<div class="card"><div class="section-head"><h2>ثبت انتقال / برگشت کالا</h2></div><div class="form-grid"><div class="field"><label>نوع</label><select id="v10TrType"><option value="TRANSFER">انتقال بین محل‌ها</option><option value="RETURN_TO_WAREHOUSE">برگشت به انبار اصلی</option></select></div><div class="field"><label>تاریخ</label><input id="v10TrDate" data-jalali="1" value="${E(today())}"></div><div class="field"><label>شیفت</label><select id="v10TrShift"><option>صبح</option><option>عصر</option><option>دو شیفت</option></select></div><div class="field"><label>ماده</label><select id="v10TrIng">${optionRows(ings,'',x=>`${x.code||''} | ${x.name} — واحد: ${ingredientUnit(x)}`)}</select></div><div class="field"><label>از محل</label><select id="v10TrFrom">${optionRows(locs,inv.settings.mainLocationId)}</select></div><div class="field"><label>به محل</label><select id="v10TrTo">${optionRows(locs,'LOC-KITCHEN')}</select></div><div class="field"><label>مقدار <small class="muted">(واحد ماده انتخابی)</small></label><input id="v10TrQty" type="number" step="0.001"></div><div class="field"><label>مسئول/تحویل‌گیرنده</label><select id="v10TrPerson"><option value="">—</option>${optionRows(A(hr?.personnel).filter(p=>p.status==='فعال'),'',p=>p.name)}</select></div><div class="field full"><label>توضیحات / علت</label><input id="v10TrNote"></div><div class="full"><button class="btn btn-primary" onclick="RayoInventoryV10.saveTransfer()">ثبت انتقال</button></div></div></div><div class="card"><div class="section-head"><h2>آخرین انتقال‌ها</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>ماده</th><th>مقدار</th><th>از</th><th>به</th><th>شیفت</th><th>مسئول</th><th>شرح</th><th></th></tr></thead><tbody>${rows.map(m=>`<tr><td>${E(m.date)}</td><td>${E(ingredient(m.ingredientId)?.name||'—')}</td><td>${F(m.quantity,3)} ${E(ingredientUnit(ingredient(m.ingredientId)))}</td><td>${E(locationName(m.fromLocationId))}</td><td>${E(locationName(m.toLocationId))}</td><td>${E(m.shift||'—')}</td><td>${E(personnelName(m.personnelId))}</td><td>${E(m.notes||'—')}</td><td><button class="btn btn-danger btn-sm" onclick="RayoInventoryV10.voidMovement('${m.id}')">ابطال</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">انتقالی ثبت نشده است.</td></tr>'}</tbody></table></div></div>${helpCard('انتقال کالا',['خرید را دوباره به‌صورت انتقال ثبت نکنید؛ ورود خرید خودکار به انبار اصلی می‌رود.','هنگام تحویل کالا به آشپزخانه، بار یا قلیان انتقال ثبت کنید.','برگشت کالا از سکشن نیز به‌صورت رویداد مستقل ثبت شود.','به‌جای حذف واقعی، انتقال اشتباه را ابطال کنید تا Audit Trail باقی بماند.'])}`}
function locationForSection(section,person){if(person?.inventoryLocationId&&locationBy(person.inventoryLocationId))return person.inventoryLocationId;const q=S(section||person?.section||person?.mainSection||person?.subSection).replace(/\s+/g,'');if(!q)return'';const l=activeLocations().find(x=>{const a=S(x.section||x.name).replace(/\s+/g,'');return a&&((a===q)||a.includes(q)||q.includes(a))});return l?.id||''}
function wasteShiftRows(date){const rows=[];for(const x of A(hr?.shiftRecords).filter(x=>S(x.date)===S(date)&&!['لغوشده','مرخصی','غیبت'].includes(S(x.status))))rows.push({personnelId:x.personnelId,shift:x.shift,section:x.section||x.subSection||''});for(const plan of A(hr?.monthlyPlans)){for(const [key,ids] of Object.entries(plan.cells||{})){const parts=S(key).split('|');if(parts.length!==3||parts[0]!==date)continue;let section='';try{section=decodeURIComponent((parts[1].split('~')[0]||''))}catch(_){section=parts[1].split('~')[0]||''}for(const pid of A(ids))if(!rows.some(r=>r.personnelId===pid&&r.shift===parts[2]))rows.push({personnelId:pid,shift:parts[2],section})}}const u=new Map;for(const r of rows)u.set(`${r.personnelId}|${r.shift}`,r);return [...u.values()]}
function wasteDeclarationStatus(date=today()){const people=A(hr?.personnel),decl=A(inv?.wasteShiftDeclarations).filter(x=>x.date===date),expected=[];for(const sh of wasteShiftRows(date)){const p=people.find(x=>x.id===sh.personnelId),pm=p?.userAccess?.permissions||{};if(!p||p.status!=='فعال'||(!pm.inventoryWaste&&!pm.inventoryConsumption))continue;const locationId=locationForSection(sh.section,p);if(!locationId)continue;const d=decl.find(x=>x.personnelId===p.id&&x.shift===sh.shift&&x.locationId===locationId);expected.push({personnelId:p.id,personnelName:p.name,shift:sh.shift,section:sh.section,locationId,declaration:d||null,status:d?'ثبت‌شده':'ثبت‌نشده'})}return{date,expected,submitted:expected.filter(x=>x.declaration).length,missing:expected.filter(x=>!x.declaration)}}
function wasteShiftDeclarationsTable(){const rows=A(inv.wasteShiftDeclarations).slice().sort((a,b)=>cmp(b.date,a.date)||S(b.createdAt).localeCompare(S(a.createdAt))).slice(0,150),st=wasteDeclarationStatus(today());return `<div class="card"><div class="section-head"><div><h2>کنترل جمع‌بندی امروز</h2><p class="muted">فقط پرسنل برنامه‌ریزی‌شده‌ای که دسترسی ثبت ضایعات/مصرف دارند انتظار می‌رود جمع‌بندی ثبت کنند.</p></div></div>${st.expected.length?`<div class="grid grid-3"><div class="kpi"><div class="label">مورد انتظار امروز</div><div class="value">${F(st.expected.length)}</div></div><div class="kpi"><div class="label">ثبت‌شده</div><div class="value positive">${F(st.submitted)}</div></div><div class="kpi"><div class="label">ثبت‌نشده</div><div class="value danger-text">${F(st.missing.length)}</div></div></div>${st.missing.length?`<div class="hint" style="margin-top:10px"><b>ثبت‌نشده:</b> ${st.missing.map(x=>`${E(x.personnelName)} — ${E(x.shift)} — ${E(locationName(x.locationId))}`).join(' | ')}</div>`:''}`:'<div class="hint">برای امروز برنامه شیفت قابل تطبیق با کاربران مجاز پیدا نشد؛ بنابراین هشدار ثبت‌نشده تولید نمی‌شود.</div>'}</div><div class="card"><div class="section-head"><div><h2>جمع‌بندی پایان شیفت پرسنل</h2><p class="muted">ثبت «بدون مورد» باعث می‌شود شیفت بدون گزارش، با شیفتی که اصلاً چیزی ثبت نکرده اشتباه نشود.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>شیفت</th><th>سکشن/محل</th><th>پرسنل</th><th>وضعیت اعلامی</th><th>رویدادهای ثبت‌شده</th><th>زمان ثبت</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.date)}</td><td>${E(r.shift||'—')}</td><td>${E(locationName(r.locationId))}</td><td>${E(r.personnelName||personnelName(r.personnelId))}</td><td>${r.declarationType==='NO_EVENT'?'<span class="badge success">بدون مورد</span>':'<span class="badge warn">دارای رویداد</span>'}</td><td>${F(r.eventCount)}</td><td>${E(r.localTime||r.createdAt||'—')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">جمع‌بندی پایان شیفتی ثبت نشده است.</td></tr>'}</tbody></table></div></div>`}
function wastePane(){const ings=A(pricing.ingredients).filter(i=>i.status!=='غیرفعال'&&i.itemType!=='NON_STOCK'),menus=A(pricing.menuItems).filter(i=>i.status!=='غیرفعال'),locs=activeLocations(),rows=[...A(inv.wasteRecords).filter(x=>x.isArchived!==true),...A(inv.consumptionRecords).filter(x=>x.isArchived!==true)].sort((a,b)=>cmp(b.date,a.date)||S(b.createdAt).localeCompare(S(a.createdAt))).slice(0,400);return `<div class="card"><div class="section-head"><div><h2>ثبت ضایعات، پرتی و مصرف خارج از فروش</h2><p class="muted">ثبت مدیریتی این فرم تأییدشده محسوب می‌شود. گزارش پرسنل تا تأیید مدیر روی موجودی اثر نمی‌گذارد.</p></div><div class="pricing-actions"><button class="btn" onclick="document.getElementById('p2WasteExcel').click()">ورود ضایعات Excel</button> <button class="btn btn-sm" onclick="RayoDownloadTemplate('waste')">⬇ دانلود نمونه</button><input hidden id="p2WasteExcel" type="file" accept=".xlsx,.xls,.csv" onchange="p2ImportWasteExcel(event)"></div></div><div class="form-grid"><div class="field"><label>تاریخ</label><input id="v10EvDate" data-jalali="1" value="${E(today())}"></div><div class="field"><label>نوع رویداد</label><select id="v10EvEventType">${Object.entries(EVENT_LABELS).map(([k,l])=>`<option value="${k}">${E(l)}</option>`).join('')}</select></div><div class="field"><label>نوع مورد</label><select id="v10EvItemType" onchange="RayoInventoryV10.eventItemType()"><option value="ingredient">ماده اولیه</option><option value="menu">آیتم منو</option></select></div><div class="field"><label>ماده / آیتم</label><select id="v10EvItem">${optionRows(ings,'',x=>`${x.code||''} | ${x.name} — واحد: ${ingredientUnit(x)}`)}</select></div><div class="field"><label>سکشن / محل</label><select id="v10EvLoc">${optionRows(locs,inv.settings.mainLocationId)}</select></div><div class="field"><label>شیفت</label><select id="v10EvShift"><option>صبح</option><option>عصر</option><option>دو شیفت</option></select></div><div class="field"><label>مقدار / تعداد <small class="muted">(طبق واحد ماده/آیتم انتخابی)</small></label><input id="v10EvQty" type="number" step="0.001"></div><div class="field"><label>شماره فیش سپیدز</label><input id="v10EvInvoice" placeholder="اختیاری"></div><div class="field"><label>فرد مرتبط</label><select id="v10EvPerson"><option value="">—</option>${optionRows(A(hr?.personnel).filter(p=>p.status==='فعال'),'',p=>p.name)}</select></div><div class="field"><label>علت</label><input id="v10EvReason" placeholder="مثلاً سوختن، اشتباه سفارش، غذای پرسنلی"></div><div class="field full"><label>توضیحات</label><textarea id="v10EvNotes"></textarea></div><div class="full"><button class="btn btn-primary" onclick="RayoInventoryV10.saveEvent()">ثبت رویداد</button></div></div></div><div class="card"><div class="section-head"><h2>سوابق رویدادها و بررسی مدیر</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>نوع</th><th>مورد</th><th>مقدار</th><th>محل</th><th>شیفت</th><th>فیش</th><th>گزارش‌دهنده/فرد مرتبط</th><th>وضعیت</th><th>توضیح</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.date)}</td><td>${E(EVENT_LABELS[r.eventType]||r.eventType||'ضایعات')}</td><td>${E(r.type==='menu'?menuItem(r.itemId)?.name:ingredient(r.itemId)?.name)||'—'}</td><td>${F(r.quantity,3)}</td><td>${E(locationName(r.locationId))}</td><td>${E(r.shift||'—')}</td><td>${E(r.invoiceNumber||'—')}</td><td>${E(r.reportedByName||personnelName(r.reportedByPersonnelId)||personnelName(r.responsiblePersonnelId))}</td><td>${E(r.reviewStatus||'تأییدشده')}</td><td>${E(r.notes||r.reason||'—')}</td><td><button class="btn btn-sm" onclick="RayoInventoryV10.reviewEvent('${r.id}','${r.recordKind==='consumption'?'consumption':'waste'}')">بررسی</button></td></tr>`).join('')||'<tr><td colspan="11" class="empty">رویدادی ثبت نشده است.</td></tr>'}</tbody></table></div></div>${wasteShiftDeclarationsTable()}${helpCard('ثبت ضایعات و مصرف مجاز',['پرسنل باید رویداد را همان زمان در پنل خودش ثبت کند؛ نام گزارش‌دهنده به معنی مقصر بودن نیست.','گزارش پرسنل ابتدا در انتظار بررسی است و تا تأیید مدیر از موجودی کم نمی‌شود.','در پایان شیفت، حتی اگر هیچ موردی رخ نداده باشد، پرسنل باید جمع‌بندی «بدون مورد» را ثبت کند.','مفقودی از ضایعات جدا گزارش می‌شود تا روند واقعی پرتی مخدوش نشود.','برای کنترل روزانه فقط ۵ تا ۱۰ قلم پرریسک هر سکشن را در شمارش دوره‌ای فعال کنید.'])}`}
function stockPane(){const locs=activeLocations(),trackedMap=new Map(A(inv.trackedIngredients).filter(t=>t.enabled!==false).map(t=>[t.ingredientId,t])),activeIngs=A(pricing.ingredients).filter(i=>i.status!=='غیرفعال'&&i.itemType!=='NON_STOCK'),ings=activeIngs.map(i=>({i,t:trackedMap.get(i.id)||{ingredientId:i.id,enabled:true,countFrequency:'MONTHLY',varianceTolerancePercent:5,defaultLocationId:inv.settings.mainLocationId}})),selected=ui.countLocation||inv.settings.mainLocationId;setTimeout(()=>window.RayoJalali?.mark?.(),0);return `<div class="card"><div class="section-head"><div><h2>شمارش دوره‌ای موجودی</h2><p class="muted">شمارش واقعی، موجودی سیستم را با واقعیت تطبیق می‌دهد. اقلام حساس روزانه، اقلام مهم هفتگی و شمارش کامل ماهانه انجام شود.</p></div></div><div class="hint"><b>شروع عملیاتی:</b> اگر از امروز کنترل انبار را آغاز می‌کنید، گزینه «موجودی اولیه / شروع کنترل» را فعال کنید و برای هر ماده هم مقدار واقعی و هم آخرین قیمت خرید بسته را وارد کنید. این شمارش بعد از تأیید مدیر Baseline جدید می‌شود و مغایرت ساختگی برای روز اول ایجاد نمی‌کند.</div></div><div class="grid grid-2"><div class="card"><div class="section-head"><h2>برنامه شمارش</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ماده</th><th>تناوب</th><th>تلورانس</th><th>محل پیش‌فرض</th><th></th></tr></thead><tbody>${ings.slice(0,600).map(x=>`<tr><td>${E(x.i.name)}</td><td>${E(x.t.countFrequency==='DAILY'?'روزانه':x.t.countFrequency==='WEEKLY'?'هفتگی':'ماهانه')}</td><td>${F(x.t.varianceTolerancePercent||5,1)}٪</td><td>${E(locationName(x.t.defaultLocationId||inv.settings.mainLocationId))}</td><td><button class="btn btn-sm" onclick="RayoInventoryV10.editCountPolicy('${x.i.id}')">تنظیم</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">ابتدا مواد مورد کنترل را در تنظیم موجودی فعال کنید.</td></tr>'}</tbody></table></div></div><div class="card"><div class="section-head"><h2>ثبت شمارش واقعی</h2></div><div class="form-grid"><div class="field"><label>تاریخ</label><input id="v10CountDate" data-jalali="1" value="${E(today())}"></div><div class="field"><label>شیفت</label><select id="v10CountShift"><option value="">انتخاب کنید</option><option>صبح</option><option>عصر</option><option>دو شیفت</option></select></div><div class="field"><label>محل / سکشن</label><select id="v10CountLoc" onchange="RayoInventoryV10.setCountLocation(this.value)"><option value="">انتخاب کنید</option>${optionRows(locs,selected)}</select></div><div class="field"><label>فیلتر تناوب</label><select id="v10CountFreq" onchange="RayoInventoryV10.setCountFrequency(this.value)"><option value="">همه</option><option value="DAILY" ${ui.countFrequency==='DAILY'?'selected':''}>روزانه</option><option value="WEEKLY" ${ui.countFrequency==='WEEKLY'?'selected':''}>هفتگی</option><option value="MONTHLY" ${ui.countFrequency==='MONTHLY'?'selected':''}>ماهانه</option></select></div><div class="field"><label>جست‌وجوی ماده</label><input id="v10CountSearch" value="${E(ui.countSearch)}" placeholder="نام یا کد ماده" oninput="RayoInventoryV10.setCountSearch(this.value)"></div><div class="field full"><label class="inline-check"><input id="v10CountOpening" type="checkbox"> موجودی اولیه / شروع کنترل از این شمارش</label></div></div><div class="hint">در شمارش عادی، موجودی مورد انتظار قبل از ثبت نمایش داده نمی‌شود. قیمت واردشده «قیمت آخرین خرید کل بسته» و به تومان است؛ واحد خرید کنار هر ماده نوشته شده است.</div><div class="table-wrap"><table class="data-table"><thead><tr><th>ماده</th><th>واحد شمارش/رسپی</th><th>موجودی واقعی</th><th>آخرین قیمت خرید کل بسته</th></tr></thead><tbody>${ings.filter(x=>(!ui.countFrequency||x.t.countFrequency===ui.countFrequency)&&(!ui.countSearch||`${x.i.name} ${x.i.code||''}`.toLowerCase().includes(S(ui.countSearch).toLowerCase()))).map(x=>`<tr><td>${E(x.i.name)}<br><small>${E(x.i.code||'')}</small></td><td>${E(x.i.recipeUnit||'واحد')}</td><td><input data-v10-count="${x.i.id}" type="number" step="0.001" placeholder="خالی = شمارش نشده"></td><td><div class="input-with-unit"><input data-v10-cost="${x.i.id}" type="text" inputmode="numeric" value="${N(x.i.lastPurchasePriceToman)?F(x.i.lastPurchasePriceToman):''}" placeholder="تومان"><small>تومان / ${E(x.i.purchaseUnit||'بسته')} — ${F(x.i.packageQuantity||1,3)} ${E(x.i.recipeUnit||'واحد')}</small></div></td></tr>`).join('')}</tbody></table></div><div style="margin-top:12px"><button class="btn btn-primary" onclick="RayoInventoryV10.submitCount()">ثبت و ارسال برای تأیید</button></div></div></div>${countReviewTable()}${helpCard('شمارش دوره‌ای',['شمارش واقعی باید توسط مسئول مشخص و ترجیحاً بدون دیدن موجودی مورد انتظار انجام شود.','در اولین روز راه‌اندازی، گزینه موجودی اولیه را فعال کنید تا شمارش به‌عنوان Baseline ثبت شود.','آخرین قیمت خرید برای ارزش‌گذاری موجودی و خسارت لازم است و می‌تواند همزمان با شمارش اولیه ثبت شود.','پس از Submit، مدیر مقدار مورد انتظار و مغایرت را می‌بیند و تأیید یا رد می‌کند.','شمارش تأییدشده مبنای جدید موجودی همان محل می‌شود.'])}`}
function countReviewTable(){const rows=A(inv.stocktakes).slice().sort((a,b)=>cmp(b.date,a.date)||S(b.createdAt).localeCompare(S(a.createdAt))).slice(0,200);return `<div class="card"><div class="section-head"><h2>شمارش‌ها و وضعیت تأیید</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>Location</th><th>شیفت</th><th>شمارش‌کننده</th><th>تعداد خطوط</th><th>وضعیت</th><th>کسری ریالی</th><th></th></tr></thead><tbody>${rows.map(st=>{const loss=A(st.lines).reduce((a,l)=>a+Math.max(0,-N(l.variance))*N(l.unitCost),0);return `<tr><td>${E(st.date)}</td><td>${E(locationName(st.locationId))}</td><td>${E(st.shift||'—')}</td><td>${E(st.countedByName||personnelName(st.countedBy)||st.countedBy||'—')}</td><td>${F(A(st.lines).length)}</td><td>${E(st.status==='approved'?'تأییدشده':st.status==='rejected'?'ردشده':'در انتظار')}</td><td>${M(loss)}</td><td><button class="btn btn-sm" onclick="RayoInventoryV10.countDetail('${st.id}')">جزئیات</button></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">شمارشی ثبت نشده است.</td></tr>'}</tbody></table></div></div>`}
function latestApprovedCount(ingredientId,locationId,target,from=''){const arr=A(inv.stocktakes).filter(st=>st.status==='approved'&&st.locationId===locationId&&beforeOrEq(st.date,target)&&(!from||cmp(st.date,from)>=0)).flatMap(st=>A(st.lines).filter(l=>l.ingredientId===ingredientId).map(l=>({...l,date:st.date,stocktakeId:st.id}))).sort((a,b)=>cmp(b.date,a.date));return arr[0]||null}
function cashSalesToman(from,to){const rows=A(cash?.reports).filter(r=>r&&inRange(r.date,from,to));if(!rows.length)return{value:0,available:false};const rial=rows.reduce((a,r)=>a+N(r.netReceivable)+N(r.snappAmount),0);return{value:rial/10,available:true}}
function wasteQuantitySummary(lines){const map=new Map();for(const x of A(lines)){const u=S(x.unit)||'واحد';if(N(x.wasteQty)>0)map.set(u,(map.get(u)||0)+N(x.wasteQty))}return [...map.entries()].map(([unit,quantity])=>({unit,quantity}))}
function periodMetrics(from,to){const ings=A(pricing.ingredients).filter(i=>i.status!=='غیرفعال'&&i.itemType!=='NON_STOCK'),locs=activeLocations();let openingValue=0,purchases=0,standard=0,waste=0,missing=0,auth=0,closingValue=0,priceEffect=0,itemSales=0,itemSalesCount=0,covered=0,totalPairs=0;const lines=[];for(const i of ings){const c=weightedCost(i.id,from,to);priceEffect+=c.priceEffect;purchases+=c.purchaseValue;let openQty=0,closeQty=0,stdQty=0,wasteQty=0,missingQty=0,authQty=0,coveragePairs=0;for(const l of locs){const op=positionBeforeDate(i.id,l.id,from);openQty+=op.quantity;const closeCount=latestApprovedCount(i.id,l.id,to,to);totalPairs++;if(closeCount){coveragePairs++;covered++}closeQty+=positionAtLocation(i.id,l.id,to).quantity;stdQty+=salesQtyForIngredientLocation(i.id,l.id,from,to);for(const m of A(inv.inventoryMovements)){if(!movementActive(m)||m.ingredientId!==i.id||m.fromLocationId!==l.id||!inRange(m.date,from,to))continue;if(WASTE_TYPES.has(m.movementType))wasteQty+=N(m.quantity);if(m.movementType==='MISSING')missingQty+=N(m.quantity);if(AUTH_TYPES.has(m.movementType))authQty+=N(m.quantity)}}const unit=N(c.unitCost),openVal=openQty*N(c.openingUnitCost||unit),closeVal=closeQty*unit;openingValue+=openVal;closingValue+=closeVal;standard+=stdQty*unit;waste+=wasteQty*unit;missing+=missingQty*unit;auth+=authQty*unit;const actual=openVal+c.purchaseValue-closeVal,unexplained=actual-(stdQty+wasteQty+missingQty+authQty)*unit;lines.push({ingredientId:i.id,name:i.name,unit:i.recipeUnit||'واحد',openQty,purchaseQty:c.purchaseQty,stdQty,wasteQty,missingQty,authQty,closeQty,unitCost:unit,actual,unexplained,coveragePairs,totalLocationPairs:locs.length})}
 for(const sp of A(inv.salesPeriods)){if(sp.status==='void')continue;for(const l of A(sp.lines)){const dt=saleDate(sp,l);if(inRange(dt,from,to)){itemSales+=N(l.quantity)*N(l.salePriceToman||menuItem(l.menuItemId)?.currentPriceToman);itemSalesCount++}}}const cashSales=cashSalesToman(from,to),salesAvailable=cashSales.available||itemSalesCount>0,sales=cashSales.available?cashSales.value:itemSales,salesSource=cashSales.available?'گزارش صندوق':itemSalesCount>0?'ریز فروش سپیدز':'داده فروش دوره آماده نیست';const actualCogs=openingValue+purchases-closingValue,unexplained=actualCogs-standard-waste-missing-auth,materialOut=standard+waste+auth;const approvedWasteEvents=A(inv.wasteRecords).filter(r=>r.status!=='void'&&r.eventType!=='MISSING'&&inRange(r.date,from,to)&&(!r.reportedByPersonnelId||['تأییدشده','ضایعات ثبت‌شده','موجه','بسته‌شده'].includes(S(r.reviewStatus)))).length;return{from,to,openingValue,purchases,available:openingValue+purchases,standard,waste,missing,auth,closingValue,actualCogs,unexplained,priceEffect,sales,salesAvailable,salesSource,itemSales,standardPct:sales?standard/sales*100:0,actualPct:sales?actualCogs/sales*100:0,grossProfit:sales-actualCogs,wastePct:sales?waste/sales*100:0,wastePctStandard:standard?waste/standard*100:0,wasteShareOfMaterialOut:materialOut?waste/materialOut*100:0,variancePct:sales?unexplained/sales*100:0,coverage:totalPairs?covered/totalPairs*100:0,wasteQuantities:wasteQuantitySummary(lines),wasteEventCount:approvedWasteEvents,lines}}
function monthRange(offset=0){const t=D(today()),m=t.match(/(\d{4})\/(\d{2})/);if(!m)return{key:'',from:'',to:''};let y=+m[1],mo=+m[2]-offset;while(mo<=0){mo+=12;y--}while(mo>12){mo-=12;y++}const key=`${y}/${String(mo).padStart(2,'0')}`;return{key,from:`${key}/01`,to:offset===0?t:`${key}/31`}}
function wasteTrend(months=6){return Array.from({length:months},(_,i)=>monthRange(months-1-i)).map(r=>({...r,...periodMetrics(r.from,r.to)}))}
function wasteTrendHtml(rows){const max=Math.max(1,...A(rows).map(x=>N(x.wastePct)));return `<div class="table-wrap"><table class="data-table"><thead><tr><th>ماه</th><th>مبلغ ضایعات</th><th>٪ از فروش</th><th>٪ از کل مصرف مواد</th><th>٪ از مصرف استاندارد</th><th>روند</th></tr></thead><tbody>${A(rows).map(x=>`<tr><td>${E(x.key)}</td><td>${M(x.waste)}</td><td><b>${x.salesAvailable?`${F(x.wastePct,2)}٪`:'—'}</b></td><td>${(x.standard+x.waste+x.auth)>0?`${F(x.wasteShareOfMaterialOut,2)}٪`:'—'}</td><td>${x.standard>0?`${F(x.wastePctStandard,2)}٪`:'—'}</td><td><div style="min-width:120px;background:#eef2f3;border-radius:999px;height:9px;overflow:hidden"><div style="width:${Math.min(100,N(x.wastePct)/max*100)}%;height:100%;background:var(--rayo,#315d68)"></div></div></td></tr>`).join('')}</tbody></table></div>`}
function wasteQuantityHtml(rows){return A(rows).length?A(rows).map(x=>`<span class="badge" style="margin-left:6px">${F(x.quantity,3)} ${E(x.unit)}</span>`).join(''):'—'}
function costPane(){if(!ui.costFrom){const t=today();ui.costFrom=t?`${t.slice(0,8)}01`:'';ui.costTo=t}const p=periodMetrics(ui.costFrom,ui.costTo),short=p.lines.filter(x=>x.unexplained>0).sort((a,b)=>b.unexplained-a.unexplained).slice(0,20),trend=wasteTrend(6);return `<div class="card"><div class="toolbar"><div class="field"><label>از تاریخ</label><input data-jalali="1" value="${E(ui.costFrom)}" onchange="RayoInventoryV10.setCostFrom(this.value)"></div><div class="field"><label>تا تاریخ</label><input data-jalali="1" value="${E(ui.costTo)}" onchange="RayoInventoryV10.setCostTo(this.value)"></div><button class="btn btn-primary" onclick="RayoInventoryV10.closePeriod()">بستن دوره / Snapshot</button></div><div class="hint">بهای واقعی مواد زمانی بیشترین اعتبار را دارد که شمارش پایان دوره پوشش کامل داشته باشد. پوشش فعلی: <b>${F(p.coverage,1)}٪</b>. مبنای فروش نسبت‌ها: <b>${E(p.salesSource)}</b>.</div></div><div class="grid grid-4"><div class="card kpi"><div class="label">موجودی ابتدای دوره</div><div class="value">${F(p.openingValue)}</div><div class="sub">تومان</div></div><div class="card kpi"><div class="label">خرید خالص دوره</div><div class="value">${F(p.purchases)}</div><div class="sub">تومان</div></div><div class="card kpi"><div class="label">بهای استاندارد مواد فروش</div><div class="value">${F(p.standard)}</div><div class="sub">${F(p.standardPct,1)}٪ فروش</div></div><div class="card kpi"><div class="label">بهای واقعی/تقریبی مواد</div><div class="value">${F(p.actualCogs)}</div><div class="sub">${F(p.actualPct,1)}٪ فروش</div></div><div class="card kpi"><div class="label">ضایعات ثبت‌شده</div><div class="value">${F(p.waste)}</div><div class="sub">${F(p.wastePct,2)}٪ فروش | ${F(p.wastePctStandard,2)}٪ مصرف</div></div><div class="card kpi"><div class="label">حجم ضایعات</div><div class="value">${F(p.wasteEventCount)}</div><div class="sub">رویداد | ${wasteQuantityHtml(p.wasteQuantities)}</div></div><div class="card kpi"><div class="label">مفقودی ثبت‌شده</div><div class="value">${F(p.missing)}</div><div class="sub">تومان / جدا از ضایعات</div></div><div class="card kpi"><div class="label">مغایرت توضیح‌داده‌نشده</div><div class="value">${F(p.unexplained)}</div><div class="sub">${F(p.variancePct,1)}٪ فروش</div></div></div><div class="card"><div class="section-head"><div><h2>روند ضایعات — ۶ ماه اخیر</h2><p class="muted">برای مقایسه تورم‌پذیر، درصد ضایعات نسبت به فروش و مصرف مواد کنار مبلغ نمایش داده می‌شود.</p></div></div>${wasteTrendHtml(trend)}</div><div class="grid grid-2"><div class="card"><div class="section-head"><h2>تفکیک مقدار از اثر قیمت</h2></div><div class="table-wrap"><table class="data-table"><tbody><tr><th>فروش خالص ثبت‌شده</th><td>${M(p.sales)}</td></tr><tr><th>مبنای فروش</th><td>${E(p.salesSource)}</td></tr><tr><th>کالای در دسترس</th><td>${M(p.available)}</td></tr><tr><th>موجودی پایان استفاده‌شده</th><td>${M(p.closingValue)}</td></tr><tr><th>اثر تغییر قیمت خرید دوره</th><td>${M(p.priceEffect)}</td></tr><tr><th>مصرف مجاز</th><td>${M(p.auth)}</td></tr><tr><th>مفقودی ثبت‌شده</th><td>${M(p.missing)}</td></tr><tr><th>مغایرت فیزیکی/مصرف توضیح‌داده‌نشده</th><td>${M(p.unexplained)}</td></tr></tbody></table></div></div><div class="card"><div class="section-head"><h2>Top مواد نیازمند بررسی</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ماده</th><th>مصرف استاندارد</th><th>ضایعات</th><th>مصرف مجاز</th><th>اختلاف</th><th></th></tr></thead><tbody>${short.map(x=>`<tr><td>${E(x.name)}</td><td>${F(x.stdQty,3)}</td><td>${F(x.wasteQty,3)}</td><td>${F(x.authQty,3)}</td><td>${M(x.unexplained)}</td><td><button class="btn btn-sm" onclick="RayoInventoryV10.drill('${x.ingredientId}','')">Drill-down</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">مورد قابل توجهی وجود ندارد.</td></tr>'}</tbody></table></div></div></div>${helpCard('بهای مواد و بستن دوره',['روش ارزش‌گذاری میانگین موزون است.','ضایعات فقط بعد از تأیید مدیر در موجودی و KPIها اثر می‌گذارد؛ مفقودی جداگانه گزارش می‌شود.','درصد ضایعات هم نسبت به فروش و هم نسبت به مصرف استاندارد مواد نمایش داده می‌شود.','برای بهای واقعی مواد قابل اتکا، شمارش واقعی پایان دوره باید پوشش بالا داشته باشد.','بستن دوره Snapshot محاسبات را نگه می‌دارد تا گزارش گذشته با تغییرات آینده جابه‌جا نشود.'])}`}
function historyPane(){const rows=A(inv.stocktakes).filter(st=>st.status==='approved').flatMap(st=>A(st.lines).map(l=>({st,l}))).sort((a,b)=>cmp(b.st.date,a.st.date)).slice(0,1000);return `<div class="card"><div class="section-head"><h2>روند مغایرت و شمارش‌های تأییدشده</h2></div><div class="toolbar"><div class="field"><label>Location</label><select onchange="RayoInventoryV10.setHistoryLocation(this.value)"><option value="">همه</option>${optionRows(activeLocations(),ui.historyLocation)}</select></div><div class="field"><label>ماده</label><select onchange="RayoInventoryV10.setHistoryIngredient(this.value)"><option value="">همه مواد</option>${A(pricing.ingredients).filter(i=>i.status!=='غیرفعال'&&i.itemType!=='NON_STOCK').slice().sort((a,b)=>S(a.name).localeCompare(S(b.name),'fa')).map(i=>`<option value="${E(i.id)}" ${i.id===ui.historyIngredient?'selected':''}>${E(i.code||'')} | ${E(i.name)}</option>`).join('')}</select></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>Location</th><th>ماده</th><th>انتظار</th><th>واقعی</th><th>مغایرت</th><th>ارزش مغایرت</th><th>وضعیت</th><th></th></tr></thead><tbody>${rows.filter(x=>(!ui.historyLocation||x.st.locationId===ui.historyLocation)&&(!ui.historyIngredient||x.l.ingredientId===ui.historyIngredient)).map(x=>`<tr><td>${E(x.st.date)}</td><td>${E(locationName(x.st.locationId))}</td><td>${E(ingredient(x.l.ingredientId)?.name||'—')}</td><td>${F(x.l.expected,3)} ${E(ingredientUnit(ingredient(x.l.ingredientId)))}</td><td>${F(x.l.actual,3)} ${E(ingredientUnit(ingredient(x.l.ingredientId)))}</td><td>${F(x.l.variance,3)} ${E(ingredientUnit(ingredient(x.l.ingredientId)))}</td><td>${M(N(x.l.variance)*N(x.l.unitCost))}</td><td>${Math.abs(N(x.l.variancePercent))>N(x.l.tolerancePercent||5)?'<span class="badge warn">نیازمند بررسی</span>':'<span class="badge success">عادی</span>'}</td><td><button class="btn btn-sm" onclick="RayoInventoryV10.drill('${x.l.ingredientId}','${x.st.locationId}')">گردش</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">رکوردی وجود ندارد.</td></tr>'}</tbody></table></div></div>`}
function renderPaneOnly(tab){if(!loaded||!inv||!pricing){setTimeout(async()=>{await ensure();try{renderView()}catch(_){}},0);return '<div class="card empty">در حال آماده‌سازی اطلاعات انبار و قیمت‌گذاری…</div>'}return tab==='overview'?overview():tab==='valuation'?valuationPane():tab==='locations'?locationsPane():tab==='transfer'?transferPane():tab==='waste'?wastePane():tab==='stock'?stockPane():tab==='cost'?costPane():historyPane()}
function renderCustom(tab){return pageHead('انبار و کنترل مصرف','کنترل موجودی، مصرف، ضایعات، شمارش و بهای مواد')+nav()+renderPaneOnly(tab)}
function wrapView(){if(typeof views==='undefined'||!views.inventory)return;if(window.__RAYO_INVENTORY_CORE_12){views.inventory.__v10=true;return}if(views.inventory.__v10)return;baseView=views.inventory;const w=function(){const q=new URLSearchParams(location.search).get('tab');if(TABS.includes(q)&&window.ops)window.ops.tab=q;if(!loaded){setTimeout(async()=>{await ensure();try{renderView()}catch(_){}},0);return pageHead('انبار، Cost Control و مغایرت','')+'<div class="card empty">در حال آماده‌سازی کنترل انبار…</div>'}const tab=window.ops?.tab||'overview';if(['overview','valuation','locations','transfer','waste','stock','cost','history'].includes(tab))return renderCustom(tab);let html=baseView();html=html.replace(/<div class="ops-tabs">[\s\S]*?<\/div>/,nav());return html};w.__v10=true;views.inventory=w}
function openModal(title,body,foot=''){const t=document.getElementById('modalTitle'),b=document.getElementById('modalBody'),f=document.getElementById('modalFoot'),m=document.getElementById('modalBackdrop');if(!t||!b||!f||!m)return;t.textContent=title;b.innerHTML=body;f.innerHTML=foot;m.classList.add('open');setTimeout(()=>window.RayoJalali?.mark?.(),0)}
async function saveBaseSettings(){inv.settings.mainLocationId=document.getElementById('v10MainLoc').value;inv.settings.defaultSalesLocationId=document.getElementById('v10DefSaleLoc').value;await saveInv('ویرایش تنظیمات Location');renderView()}
function editLocation(id=''){const l=id?A(inv.locations).find(x=>x.id===id):{code:'',name:'',type:'section',section:'',isActive:true,notes:''};openModal(id?'ویرایش Location':'Location جدید',`<div class="form-grid"><div class="field"><label>کد</label><input id="v10LocCode" value="${E(l.code)}"></div><div class="field"><label>نام</label><input id="v10LocName" value="${E(l.name)}"></div><div class="field"><label>نوع</label><select id="v10LocType"><option value="main" ${l.type==='main'?'selected':''}>انبار اصلی</option><option value="section" ${l.type!=='main'?'selected':''}>مصرفی/سکشن</option></select></div><div class="field"><label>سکشن</label><input id="v10LocSection" value="${E(l.section||'')}"></div><div class="field"><label>فعال</label><select id="v10LocActive"><option value="1" ${l.isActive!==false?'selected':''}>بله</option><option value="0" ${l.isActive===false?'selected':''}>خیر</option></select></div><div class="field full"><label>توضیحات</label><textarea id="v10LocNotes">${E(l.notes||'')}</textarea></div></div>`,`<button class="btn" onclick="closeModal()">انصراف</button><button class="btn btn-primary" onclick="RayoInventoryV10.saveLocation('${E(id)}')">ذخیره</button>`)}
async function saveLocation(id=''){const code=S(document.getElementById('v10LocCode').value),name=S(document.getElementById('v10LocName').value);if(!code||!name)return toastX('کد و نام Location الزامی است',true);let l=id?A(inv.locations).find(x=>x.id===id):null;if(!l){l={id:uid('LOC',inv.locations)};inv.locations.push(l)}Object.assign(l,{code,name,type:document.getElementById('v10LocType').value,section:S(document.getElementById('v10LocSection').value),isActive:document.getElementById('v10LocActive').value==='1',notes:S(document.getElementById('v10LocNotes').value),updatedAt:now()});await saveInv(id?'ویرایش Location':'افزودن Location');closeModal();renderView()}
