async function saveTransfer(){const type=document.getElementById('v10TrType').value,date=D(document.getElementById('v10TrDate').value),ingredientId=document.getElementById('v10TrIng').value,fromLocationId=document.getElementById('v10TrFrom').value,toLocationId=type==='RETURN_TO_WAREHOUSE'?inv.settings.mainLocationId:document.getElementById('v10TrTo').value,quantity=N(document.getElementById('v10TrQty').value),personnelId=document.getElementById('v10TrPerson').value,shift=document.getElementById('v10TrShift').value,notes=S(document.getElementById('v10TrNote').value);if(!date||!ingredientId||!fromLocationId||!toLocationId||quantity<=0)return toastX('تاریخ، ماده، مبدا، مقصد و مقدار معتبر الزامی است',true);if(fromLocationId===toLocationId)return toastX('مبدا و مقصد نمی‌توانند یکسان باشند',true);inv.inventoryMovements.push({id:uid('MOV',inv.inventoryMovements),date,movementType:type,ingredientId,quantity,fromLocationId,toLocationId,reasonCode:type,personnelId,shift,notes,status:'posted',createdAt:now(),createdBy:actor()});await saveInv('ثبت انتقال موجودی');renderView()}
async function voidMovement(id){const m=A(inv.inventoryMovements).find(x=>x.id===id);if(!m)return;const reason=prompt('علت ابطال این رویداد را بنویسید:');if(reason===null)return;m.status='void';m.voidReason=S(reason);m.voidedAt=now();m.voidedBy=actor();await saveInv('ابطال حرکت موجودی');renderView()}
function eventItemType(){const type=document.getElementById('v10EvItemType')?.value,sel=document.getElementById('v10EvItem');if(!sel)return;const rows=type==='menu'?A(pricing.menuItems).filter(i=>i.status!=='غیرفعال'):A(pricing.ingredients).filter(i=>i.status!=='غیرفعال'&&i.itemType!=='NON_STOCK');sel.innerHTML=optionRows(rows,'',x=>`${x.code||''} | ${x.name}`)}
async function saveEvent(){const date=D(document.getElementById('v10EvDate').value),eventType=document.getElementById('v10EvEventType').value,type=document.getElementById('v10EvItemType').value,itemId=document.getElementById('v10EvItem').value,locationId=document.getElementById('v10EvLoc').value,shift=document.getElementById('v10EvShift').value,quantity=N(document.getElementById('v10EvQty').value),invoiceNumber=S(document.getElementById('v10EvInvoice').value),responsiblePersonnelId=document.getElementById('v10EvPerson').value,reason=S(document.getElementById('v10EvReason').value),notes=S(document.getElementById('v10EvNotes').value);if(!date||!itemId||!locationId||quantity<=0)return toastX('تاریخ، مورد، سکشن/محل و مقدار معتبر الزامی است',true);if(!notes&&!reason)return toastX('علت یا توضیح رویداد را وارد کنید',true);const common={date,eventType,type,itemId,locationId,shift,quantity,invoiceNumber,responsiblePersonnelId,reason,notes,reviewStatus:'تأییدشده',reportedByName:actor(),reviewedBy:actor(),reviewedAt:now(),createdBy:actor(),createdAt:now(),status:'posted'};let rec;if(AUTH_TYPES.has(eventType)){rec={id:uid('CON',inv.consumptionRecords),recordKind:'consumption',...common};inv.consumptionRecords.push(rec)}else{rec={id:uid('WST',inv.wasteRecords),recordKind:'waste',known:true,causeKnown:true,...common};inv.wasteRecords.push(rec)}syncWasteMovement(rec);await saveInv('ثبت رویداد مصرف/ضایعات');renderView()}
function recordByKind(id,kind){return kind==='consumption'?A(inv.consumptionRecords).find(x=>x.id===id):A(inv.wasteRecords).find(x=>x.id===id)}
function reviewEvent(id,kind){const r=recordByKind(id,kind);if(!r)return;openModal('بررسی رویداد مواد',`<div class="form-grid"><div class="field"><label>وضعیت بررسی</label><select id="v10RevStatus">${['در انتظار بررسی','نیازمند پیگیری','تأییدشده','ردشده','موجه','خطای عملیاتی','بسته‌شده'].map(x=>`<option ${x===(r.reviewStatus||'در انتظار بررسی')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>مقدار تأییدشده <small class="muted">(${E(r.type==='menu'?'عدد':ingredientUnit(ingredient(r.itemId)))})</small></label><input id="v10RevQty" type="number" step="0.001" value="${N(r.quantity)}"></div><div class="field full"><label>نظر مدیر</label><textarea id="v10RevNote">${E(r.managerNote||'')}</textarea></div><div class="field full"><label>شرح اولیه</label><div class="hint">${E(r.notes||r.reason||'—')}</div></div></div>`,`<button class="btn" onclick="closeModal()">انصراف</button><button class="btn btn-primary" onclick="RayoInventoryV10.saveReview('${id}','${kind}')">ثبت بررسی</button>`)}
async function saveReview(id,kind){const r=recordByKind(id,kind);if(!r)return;const next=document.getElementById('v10RevStatus').value,note=S(document.getElementById('v10RevNote').value),qty=N(document.getElementById('v10RevQty').value),changed=Math.abs(qty-N(r.quantity))>1e-9;if((next==='ردشده'||changed)&&!note)return toastX('برای رد کردن یا اصلاح مقدار، توضیح مدیر الزامی است',true);if(qty<=0&&next!=='ردشده')return toastX('مقدار تأییدشده باید بیشتر از صفر باشد',true);if(changed){r.originalQuantity=N(r.originalQuantity)||N(r.quantity);r.quantity=qty;r.adjustedBy=actor();r.adjustedAt=now()}r.reviewStatus=next;r.managerNote=note;r.reviewedBy=actor();r.reviewedAt=now();r.status=next==='ردشده'?'void':(['تأییدشده','موجه','بسته‌شده'].includes(next)?'posted':'pending');syncWasteMovement(r);for(const m of A(inv.inventoryMovements).filter(x=>x.referenceId===id||x.id===r.movementId)){m.reviewStatus=r.reviewStatus;m.managerNote=r.managerNote;m.reviewedBy=r.reviewedBy;m.reviewedAt=r.reviewedAt;if(next==='ردشده')m.status='void';else if(['تأییدشده','موجه','بسته‌شده'].includes(next))m.status='posted';else m.status='pending'}inv.changeLog.push({at:now(),action:'بررسی رویداد مواد',entityId:id,status:next,quantity:r.quantity,note,actor:actor()});await saveInv('بررسی رویداد مواد');closeModal();renderView()}
function setCountLocation(v){ui.countLocation=v;renderView()} function setCountFrequency(v){ui.countFrequency=v;renderView()}
